import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 급여명세서는 마감 이후 상태(마감, 전표처리)의 지급일에 대해서만 발송한다
const CLOSED_STATUSES = ['마감', '전표처리'];

function isId(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  if (typeof v === 'string') {
    return /^[0-9]+$/.test(v);
  }
  return false;
}

function toInt(v: unknown, fallback: number): number {
  if (v === undefined || v === null || v === '') {
    return fallback;
  }
  const n = Number(v);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '숫자 형식이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr02117Controller {
  @Post('/payrolls/send-statements')
  @HttpCode(200)
  async sendPayrollStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    if (!isId(data['paydayId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일을 선택해 주세요.');
    }
    const rawIds = data['employeeIds'];
    let employeeIds: unknown[] = [];
    if (rawIds !== undefined && rawIds !== null) {
      if (!Array.isArray(rawIds) || !rawIds.every(isId)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID 목록 형식이 올바르지 않습니다.');
      }
      employeeIds = rawIds;
    }
    const paydayId = String(data['paydayId']);
    return transaction(async (db) => {
      const paydays = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (paydays.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (!CLOSED_STATUSES.includes(String(paydays[0]['status']))) {
        throw new ApiError(409, 'PAYROLL_NOT_CLOSED', '마감되지 않은 급여는 명세서를 발송할 수 없습니다.');
      }
      const failures: { employeeId: number | string; reason: string }[] = [];
      let successCount = 0;
      if (employeeIds.length === 0) {
        successCount = await db.execute(
          'UPDATE payroll SET statement_sent_at = now(), updated_at = now() WHERE payday_id = CAST(:paydayId AS bigint)',
          { paydayId },
        );
      } else {
        for (const id of employeeIds) {
          const employeeId = String(id);
          const changed = await db.execute(
            'UPDATE payroll SET statement_sent_at = now(), updated_at = now() WHERE payday_id = CAST(:paydayId AS bigint) AND employee_id = CAST(:employeeId AS bigint)',
            { paydayId, employeeId },
          );
          if (changed > 0) {
            successCount += changed;
          } else {
            failures.push({ employeeId: Number(employeeId), reason: '해당 지급일의 급여 내역이 없습니다.' });
          }
        }
      }
      return { successCount, failures };
    });
  }

  @Get('/payrolls/my-statements')
  async listMyPayrollStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const page = toInt(query['page'], 0);
    let size = toInt(query['size'], DEFAULT_SIZE);
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const rawPayday = query['paydayId'];
    let paydayId: string | null = null;
    if (rawPayday !== undefined && rawPayday !== null && rawPayday !== '') {
      if (!isId(rawPayday)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일 ID 형식이 올바르지 않습니다.');
      }
      paydayId = String(rawPayday);
    }
    return transaction(async (db) => {
      // 본인 것만, 발송된 명세서만 (가정: 발송 전 명세서는 임직원에게 보이지 않는다)
      const where =
        'employee_id = CAST(:userId AS bigint) AND statement_sent_at IS NOT NULL AND (CAST(:paydayId AS bigint) IS NULL OR payday_id = CAST(:paydayId AS bigint))';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM payroll WHERE ' + where,
        { userId: user.id, paydayId },
      );
      const items = await db.query(
        'SELECT payroll_id AS "payrollId", payday_id AS "paydayId", total_payment_amount AS "totalPaymentAmount", total_deduction_amount AS "totalDeductionAmount", net_pay_amount AS "netPayAmount", statement_sent_at AS "statementSentAt" FROM payroll WHERE ' +
          where +
          ' ORDER BY payday_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { userId: user.id, paydayId, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

