import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr02117Page({ role, notify }: PageProps) {
  const [paydayFilter, setPaydayFilter] = useState<number | string>('');
  const [applied, setApplied] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [picked, setPicked] = useState<number | string>('');
  const [employeeIds, setEmployeeIds] = useState<(number | string)[]>([]);
  const [result, setResult] = useState<Row | undefined>(undefined);

  const list = useData<Page>(
    () => call<Page>('GET', '/payrolls/my-statements', role, undefined, { paydayId: applied, page, size: 20 }),
    [applied, page, role],
  );

  const failures = (result?.['failures'] as Row[] | undefined) ?? [];

  function addEmployee(v: number | string) {
    if (v === '' || employeeIds.includes(v)) {
      setPicked('');
      return;
    }
    setEmployeeIds([...employeeIds, v]);
    setPicked('');
  }

  function openSend() {
    setPaydayId('');
    setPicked('');
    setEmployeeIds([]);
    setOpen(true);
  }

  async function send() {
    if (paydayId === '') {
      throw new Error('급여 지급일을 선택해 주세요.');
    }
    const body: Row = { paydayId };
    if (employeeIds.length > 0) {
      body['employeeIds'] = employeeIds;
    }
    const res = await call<Row>('POST', '/payrolls/send-statements', role, body);
    setResult(res);
    setOpen(false);
    notify('급여명세서를 발송했습니다.');
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>본인 급여명세서</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(paydayFilter);
          }}
          onReset={() => {
            setPaydayFilter('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label="급여 지급일 ID">
            <LookupSelect table="payday" role={role} value={paydayFilter} onChange={setPaydayFilter} />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openSend}>
            급여명세서 발송
          </button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={list.data?.items ?? []}
          empty="조회된 급여명세서가 없습니다."
          columns={[
            { key: 'paydayId', label: '급여 지급일 ID', render: (r) => <RefName table="payday" role={role} value={r['paydayId']} /> },
            { key: 'totalPaymentAmount', label: '지급 합계', render: (r) => <Num value={r['totalPaymentAmount']} /> },
            { key: 'totalDeductionAmount', label: '공제 합계', render: (r) => <Num value={r['totalDeductionAmount']} /> },
            { key: 'netPayAmount', label: '실수령액', render: (r) => <Num value={r['netPayAmount']} /> },
            { key: 'statementSentAt', label: '급여명세서 발송 시각', render: (r) => <DateText value={r['statementSentAt']} time /> },
          ]}
        />
        <Pager page={list.data?.page ?? 0} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>발송 결과</h2>
        <Tiles
          items={[
            ['발송 성공', result ? <Num value={result['successCount']} /> : '-'],
            ['발송 실패', result ? <Num value={failures.length} /> : '-'],
          ]}
        />
        {failures.length > 0 ? (
          <DataTable
            rows={failures}
            columns={[
              { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
              { key: 'reason', label: '실패 사유' },
            ]}
          />
        ) : null}
      </section>
      {open ? (
        <Drawer title="급여명세서 발송" onClose={() => setOpen(false)}>
          <Form onSubmit={send} submit="발송" note="대상을 고르지 않으면 해당 지급일의 전체 임직원에게 발송합니다.">
            <Field label="급여 지급일 ID" required>
              <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} />
            </Field>
            <Field label="선택 임직원 ID 목록" wide hint="고르면 목록에 추가됩니다. 비워 두면 전체">
              <LookupSelect table="employee" role={role} value={picked} onChange={addEmployee} />
              <div>
                {employeeIds.map((id) => (
                  <button key={String(id)} type="button" onClick={() => setEmployeeIds(employeeIds.filter((x) => x !== id))}>
                    <RefName table="employee" role={role} value={id} /> ✕
                  </button>
                ))}
              </div>
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
